1	/**
2	 * Main Cloudflare Worker entry point for the Paperclip API.
3	 *
4	 * This file:
5	 *   1. Creates a Hono app and mounts route definitions extracted from the
6	 *      server's Express routers via the express-router-bridge.
7	 *   2. Implements the first-run setup gate (redirects to /setup until KV flag is set).
8	 *   3. Handles Cloudflare Queues message batches (plugin job fanout, heartbeat dispatch).
9	 *   4. Handles Cloudflare Cron Triggers (heartbeat sweep, budget checks, DB backup).
10	 *   5. Re-exports all Durable Object and Workflow classes so Wrangler can
11	 *      register them -- they must be named exports from the Worker's main module.
12	 *
13	 * Routes skipped (use Node-only features -- left as 501 TODOs):
14	 *   - adapterRoutes       -- reads packages from disk
15	 *   - pluginRoutes        -- SSE, child processes, scoped plugin API
16	 *   - pluginUiStaticRoutes -- fs.readFileSync / res.sendFile
17	 *   - companySkillRoutes  -- local filesystem (CF version: cf-company-skills.ts)
18	 *   - accessRoutes        -- reads bundled SKILL.md files from disk
19	 *   - instanceDatabaseBackupRoutes -- pg_dump
20	 *
21	 * Architecture note on per-request DB injection:
22	 *   Route handlers (Handler functions) capture a `db` and `storage` reference
23	 *   from the service factories at the time the Express Router is built. Because
24	 *   the real `db` comes from Hyperdrive (a per-request binding), we rebuild the
25	 *   Express Routers on the FIRST request of each cold start and cache the
26	 *   extracted route definitions for subsequent requests in the same isolate.
27	 *
28	 *   Hono routes are registered at module load time as thin proxies that
29	 *   forward to the lazily-built route definitions.
30	 */
31	
32	import { Hono } from "hono";
33	import { createSetupApp } from "./setup.js";
34	import { bootCloudflare } from "../boot.js";
35	import { SidecarClient } from "../sidecar-client.js";
36	import { CfCompanySkillsService } from "../services/cf-company-skills.js";
37	import { CfAgentInstructionsService } from "../services/cf-agent-instructions.js";
38	import { createHyperdriveDb } from "../db/hyperdrive.js";
39	import { R2Provider } from "../storage/r2-provider.js";
40	import { createCfStorageService } from "../storage/cf-storage-service.js";
41	import { extractRoutesFromRouter } from "../http/express-router-bridge.js";
42	import { resolveActorFromRequest } from "../auth/resolve-actor.js";
43	import { runHeartbeatSweep } from "../cron/heartbeat-sweep.js";
44	import { HttpError } from "../../../../server/src/errors.js";
45	import type { RouteDefinition } from "../../../../server/src/http/types.js";
46	import type { StorageService } from "../../../../server/src/storage/types.js";
47	import type { Db } from "@paperclipai/db";
48	
49	// Server-side route factories
50	import { companyRoutes } from "../../../../server/src/routes/companies.js";
51	import { agentRoutes } from "../../../../server/src/routes/agents.js";
52	import { assetRoutes } from "../../../../server/src/routes/assets.js";
53	import { projectRoutes } from "../../../../server/src/routes/projects.js";
54	import { issueRoutes } from "../../../../server/src/routes/issues.js";
55	import { issueTreeControlRoutes } from "../../../../server/src/routes/issue-tree-control.js";
56	import { routineRoutes } from "../../../../server/src/routes/routines.js";
57	import { environmentRoutes } from "../../../../server/src/routes/environments.js";
58	import { executionWorkspaceRoutes } from "../../../../server/src/routes/execution-workspaces.js";
59	import { goalRoutes } from "../../../../server/src/routes/goals.js";
60	import { approvalRoutes } from "../../../../server/src/routes/approvals.js";
61	import { secretRoutes } from "../../../../server/src/routes/secrets.js";
62	import { costRoutes } from "../../../../server/src/routes/costs.js";
63	import { activityRoutes } from "../../../../server/src/routes/activity.js";
64	import { dashboardRoutes } from "../../../../server/src/routes/dashboard.js";
65	import { userProfileRoutes } from "../../../../server/src/routes/user-profiles.js";
66	import { sidebarBadgeRoutes } from "../../../../server/src/routes/sidebar-badges.js";
67	import { sidebarPreferenceRoutes } from "../../../../server/src/routes/sidebar-preferences.js";
68	import { inboxDismissalRoutes } from "../../../../server/src/routes/inbox-dismissals.js";
69	import { instanceSettingsRoutes } from "../../../../server/src/routes/instance-settings.js";
70	import { llmRoutes } from "../../../../server/src/routes/llms.js";
71	import { authRoutes } from "../../../../server/src/routes/auth.js";
72	
73	// ---------------------------------------------------------------------------
74	// Env -- Cloudflare bindings injected at runtime
75	// ---------------------------------------------------------------------------
76	
77	export interface Env {
78	  // Databases
79	  HYPERDRIVE: { connectionString: string };
80	
81	  // Object storage
82	  PAPERCLIP_STORAGE: R2Bucket;
83	
84	  // KV -- setup flags, hot config, session cache
85	  PAPERCLIP_KV: KVNamespace;
86	
87	  // Durable Object namespaces
88	  TASK_DO: DurableObjectNamespace;
89	  AGENT_RUN_DO: DurableObjectNamespace;
90	  SCHEDULER_DO: DurableObjectNamespace;
91	
92	  // Queues
93	  PAPERCLIP_QUEUE: Queue;
94	
95	  // Workflows
96	  HEARTBEAT_WORKFLOW: Workflow;
97	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
98	
99	  // Vars (set in wrangler.toml [vars])
100	  DEPLOYMENT_PLATFORM: string;
101	  DEPLOYMENT_MODE: string;
102	  DEPLOYMENT_EXPOSURE: string;
103	  STORAGE_R2_BUCKET?: string;
104	  STORAGE_R2_PREFIX?: string;
105	
106	  // Sidecar -- the Node server running alongside the Workers deployment.
107	  SIDECAR_URL: string;
108	  SIDECAR_API_KEY: string;
109	}
110	
111	// ---------------------------------------------------------------------------
112	// Per-request route resolution
113	//
114	// Route handlers close over service instances which close over the DB
115	// connection. CF Workers prohibits reusing I/O objects (TCP sockets) across
116	// requests, so we rebuild DB + route tables on every request.
117	//
118	// Route path patterns (regexp, paramNames) are static and are cached.
119	// ---------------------------------------------------------------------------
120	
121	interface CompiledRoute {
122	  route: RouteDefinition;
123	  re: RegExp;
124	  paramNames: string[];
125	}
126	
127	// Cached route path patterns — these don't depend on DB so they survive
128	// across requests in the same isolate.
129	let compiledPathCache: Array<{ method: string; path: string; re: RegExp; paramNames: string[] }> | null = null;
130	
131	// Convert an Express-style path pattern (with :param segments) to a RegExp.
132	function pathToRegex(path: string): { re: RegExp; paramNames: string[] } {
133	  const paramNames: string[] = [];
134	  const pattern = path
135	    .replace(/[$()*+.?[\\\]^{|}]/g, "\\$&")
136	    .replace(/:([a-zA-Z_][a-zA-Z0-9_]*)/g, (_match, name: string) => {
137	      paramNames.push(name);
138	      return "([^/]+)";
139	    });
140	  return { re: new RegExp(`^${pattern}$`), paramNames };
141	}
142	
143	function buildRequestResources(env: Env) {
144	  const db = createHyperdriveDb(env.HYPERDRIVE);
145	  const r2Provider = new R2Provider(env.PAPERCLIP_STORAGE, {
146	    bucket: env.STORAGE_R2_BUCKET ?? "paperclip-storage",
147	    prefix: env.STORAGE_R2_PREFIX ?? "",
148	  });
149	  const storage = createCfStorageService(r2Provider) as unknown as StorageService;
150	
151	  function ext(router: unknown, prefix: string): RouteDefinition[] {
152	    return extractRoutesFromRouter(router, prefix);
153	  }
154	
155	  const routes: RouteDefinition[] = [
156	    ...ext(companyRoutes(db, storage), "/api/companies"),
157	    ...ext(agentRoutes(db, {}), "/api"),
158	    ...ext(assetRoutes(db, storage), "/api"),
159	    ...ext(projectRoutes(db), "/api"),
160	    ...ext(issueRoutes(db, storage, {}), "/api"),
161	    ...ext(issueTreeControlRoutes(db), "/api"),
162	    ...ext(routineRoutes(db, {}), "/api"),
163	    ...ext(environmentRoutes(db, {}), "/api"),
164	    ...ext(executionWorkspaceRoutes(db), "/api"),
165	    ...ext(goalRoutes(db), "/api"),
166	    ...ext(approvalRoutes(db, {}), "/api"),
167	    ...ext(secretRoutes(db), "/api"),
168	    ...ext(costRoutes(db, {}), "/api"),
169	    ...ext(activityRoutes(db), "/api"),
170	    ...ext(dashboardRoutes(db), "/api"),
171	    ...ext(userProfileRoutes(db), "/api"),
172	    ...ext(sidebarBadgeRoutes(db), "/api"),
173	    ...ext(sidebarPreferenceRoutes(db), "/api"),
174	    ...ext(inboxDismissalRoutes(db), "/api"),
175	    ...ext(instanceSettingsRoutes(db), "/api"),
176	    ...ext(llmRoutes(db), "/api"),
177	    ...ext(authRoutes(db), "/api"),
178	  ];
179	
180	  if (!compiledPathCache) {
181	    compiledPathCache = routes.map((r) => ({ method: r.method, path: r.path, ...pathToRegex(r.path) }));
182	    console.log(`[CF Worker] Compiled ${compiledPathCache.length} route patterns`);
183	  }
184	
185	  const compiled: CompiledRoute[] = routes.map((route, i) => ({
186	    route,
187	    re: compiledPathCache![i]!.re,
188	    paramNames: compiledPathCache![i]!.paramNames,
189	  }));
190	
191	  return { compiled, db, storage };
192	}
193	
194	// ---------------------------------------------------------------------------
195	// Hono app
196	// ---------------------------------------------------------------------------
197	
198	const app = new Hono<{ Bindings: Env }>();
199	
200	// Health check -- always reachable
201	app.get("/api/health", (c) =>
202	  c.json({
203	    status: "ok",
204	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
205	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
206	    ts: new Date().toISOString(),
207	  }),
208	);
209	
210	// First-run setup gate
211	app.use("*", async (c, next) => {
212	  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
213	    return next();
214	  }
215	  // In local_trusted mode the DB is already set up; skip the KV gate.
216	  if (c.env.DEPLOYMENT_MODE === "local_trusted") {
217	    return next();
218	  }
219	  const setupCompleted = await c.env.PAPERCLIP_KV.get("SETUP_COMPLETED");
220	  if (setupCompleted !== "true") {
221	    return c.redirect("/setup");
222	  }
223	  return next();
224	});
225	
226	// Setup sub-app
227	app.all("/setup/*", async (c) => {
228	  const setupSub = createSetupApp(c.env);
229	  const url = new URL(c.req.url);
230	  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
231	  const rewritten = new Request(url.toString(), c.req.raw);
232	  return setupSub.fetch(rewritten);
233	});
234	
235	app.all("/setup", async (c) => {
236	  const setupSub = createSetupApp(c.env);
237	  const url = new URL(c.req.url);
238	  url.pathname = "/";
239	  const rewritten = new Request(url.toString(), c.req.raw);
240	  return setupSub.fetch(rewritten);
241	});
242	
243	// ---------------------------------------------------------------------------
244	// Main API catch-all -- routes through cached route definitions
245	//
246	// We use a single wildcard handler for /api/* rather than registering one
247	// Hono route per server route definition. This avoids blowing Hono's internal
248	// route trie limit and is simpler to reason about.
249	//
250	// Routing is done manually: iterate the route definitions, match method and
251	// path pattern, and delegate to the handler.
252	// ---------------------------------------------------------------------------
253	
254	function getCompiledRoutes(env: Env) {
255	  return buildRequestResources(env);
256	}
257	
258	// R2-native upload endpoints (registered before the catch-all)
259	app.put("/api/assets/:assetId/upload", async (c) => {
260	  const { assets } = await import("../../../db/src/schema/index.js");
261	  const { eq } = await import("drizzle-orm");
262	  const { forbidden, notFound, badRequest } = await import("../../../../server/src/errors.js");
263	
264	  const env = c.env;
265	  const { db } = buildRequestResources(env);
266	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted" ? "local_trusted" as const : "authenticated" as const;
267	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
268	
269	  try {
270	    const assetId = c.req.param("assetId");
271	    if (!assetId) return c.json({ error: "Missing assetId" }, 400);
272	    const assetRow = await db.select().from(assets).where(eq(assets.id, assetId)).then((rows) => rows[0] ?? null);
273	    if (!assetRow) throw notFound("Asset not found");
274	
275	    if (!actor) throw forbidden("Authentication required");
276	    if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(assetRow.companyId)) {
277	      throw forbidden("No access to this company");
278	    }
279	    if (actor.type === "agent" && actor.companyId !== assetRow.companyId) {
280	      throw forbidden("No access to this company");
281	    }
282	
283	    const body = c.req.raw.body;
284	    if (!body) throw badRequest("Empty request body");
285	    const key = `assets/${assetRow.companyId}/${assetId}`;
286	    await env.PAPERCLIP_STORAGE.put(key, body, { httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" } });
287	    return c.json({ ok: true, key });
288	  } catch (err) {
289	    if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
290	    console.error("[CF Worker] PUT /api/assets/:assetId/upload", err);
291	    return c.json({ error: "Internal Server Error" }, 500);
292	  }
293	});
294	
295	app.post("/api/issues/:issueId/attachments/upload", async (c) => {
296	  const { issues } = await import("../../../db/src/schema/index.js");
297	  const { eq } = await import("drizzle-orm");
298	  const { forbidden, notFound, badRequest } = await import("../../../../server/src/errors.js");
299	
300	  const env = c.env;
301	  const { db } = buildRequestResources(env);
302	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted" ? "local_trusted" as const : "authenticated" as const;
303	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
304	
305	  try {
306	    const issueId = c.req.param("issueId");
307	    if (!issueId) return c.json({ error: "Missing issueId" }, 400);
308	    const issueRow = await db.select({ id: issues.id, companyId: issues.companyId })
309	      .from(issues).where(eq(issues.id, issueId)).then((rows) => rows[0] ?? null);
310	    if (!issueRow) throw notFound("Issue not found");
311	
312	    if (!actor) throw forbidden("Authentication required");
313	    if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(issueRow.companyId)) {
314	      throw forbidden("No access to this company");
315	    }
316	    if (actor.type === "agent" && actor.companyId !== issueRow.companyId) {
317	      throw forbidden("No access to this company");
318	    }
319	
320	    const body = c.req.raw.body;
321	    if (!body) throw badRequest("Empty request body");
322	    const filename = (c.req.header("x-filename") ?? "attachment").replace(/[^a-zA-Z0-9._-]/g, "_");
323	    const key = `issues/${issueRow.companyId}/${issueId}/attachments/${filename}`;
324	    await env.PAPERCLIP_STORAGE.put(key, body, { httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" } });
325	    return c.json({ ok: true, key, filename });
326	  } catch (err) {
327	    if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
328	    console.error("[CF Worker] POST /api/issues/:issueId/attachments/upload", err);
329	    return c.json({ error: "Internal Server Error" }, 500);
330	  }
331	});
332	
333	// Main API catch-all -- manual routing through cached route definitions
334	app.all("/api/*", async (c) => {
335	  const { compiled, db, storage } = getCompiledRoutes(c.env);
336	  // Strip trailing slash so /api/companies/ matches /api/companies routes.
337	  const rawPathname = new URL(c.req.url).pathname;
338	  const pathname = rawPathname.length > 1 ? rawPathname.replace(/\/$/, "") : rawPathname;
339	  const method = c.req.method.toUpperCase();
340	
341	  for (const { route, re, paramNames } of compiled) {
342	    if (route.method !== method) continue;
343	    const match = re.exec(pathname);
344	    if (!match) continue;
345	
346	    // Build param map for this match
347	    const params: Record<string, string> = {};
348	    for (let i = 0; i < paramNames.length; i++) {
349	      params[paramNames[i]!] = match[i + 1]!;
350	    }
351	
352	    // Wrap ctx.param to return from our extracted params
353	    const actor = await resolveActorFromRequest(
354	      c.req.raw,
355	      db,
356	      {
357	        deploymentMode: c.env.DEPLOYMENT_MODE === "local_trusted"
358	          ? "local_trusted"
359	          : "authenticated",
360	      },
361	    );
362	
363	    const ctx: import("../../../../server/src/http/types.js").RequestCtx = {
364	      method: c.req.method,
365	      url: new URL(c.req.url),
366	      headers: new Headers(c.req.raw.headers),
367	      json<T>(): Promise<T> { return c.req.json<T>(); },
368	      text(): Promise<string> { return c.req.text(); },
369	      param(name: string): string | undefined { return params[name]; },
370	      query(name: string): string | undefined { return c.req.query(name); },
371	      actor,
372	      db,
373	      storage,
374	    };
375	
376	    try {
377	      return await route.handler(ctx);
378	    } catch (err) {
379	      if (err instanceof HttpError) {
380	        return Response.json(
381	          { error: err.message, ...(err.details !== undefined ? { details: err.details } : {}) },
382	          { status: err.status },
383	        );
384	      }
385	      console.error(
386	        `[CF Worker] Unhandled error in ${route.method} ${route.path}: ${
387	          err instanceof Error ? err.stack ?? err.message : String(err)
388	        }`,
389	      );
390	      return Response.json({ error: "Internal Server Error" }, { status: 500 });
391	    }
392	  }
393	
394	  // No route matched
395	  return c.json(
396	    {
397	      error: "This API route is not available in the Cloudflare Workers deployment.",
398	      code: "NOT_IMPLEMENTED",
399	    },
400	    501,
401	  );
402	});
403	
404	// Catch-all SPA fallback
405	app.all("*", (c) =>
406	  c.html(
407	    `<!DOCTYPE html>
408	<html><head><meta charset="UTF-8"><title>Paperclip</title></head>
409	<body>
410	  <p>Loading Paperclip UI... If this persists, the Pages build may not be deployed yet.</p>
411	</body></html>`,
412	  ),
413	);
414	
415	// ---------------------------------------------------------------------------
416	// Default export -- Workers fetch handler
417	// ---------------------------------------------------------------------------
418	
419	export default {
420	  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
421	    // Boot the Cloudflare implementations on first request (idempotent).
422	    bootCloudflare(env);
423	
424	    // Route patterns are compiled lazily on first request; no warm-up needed.
425	
426	    // CF service layer -- instantiated per-request (Workers are stateless).
427	    const sidecar = new SidecarClient({
428	      baseUrl: env.SIDECAR_URL,
429	      apiKey: env.SIDECAR_API_KEY,
430	    });
431	    const skillsService = new CfCompanySkillsService(env.PAPERCLIP_STORAGE, sidecar);
432	    const instructionsService = new CfAgentInstructionsService(env.PAPERCLIP_STORAGE);
433	
434	    void skillsService;
435	    void instructionsService;
436	
437	    return app.fetch(request, env, ctx);
438	  },
439	
440	  // -------------------------------------------------------------------------
441	  // Queues consumer
442	  // -------------------------------------------------------------------------
443	  async queue(batch: MessageBatch<unknown>, env: Env): Promise<void> {
444	    for (const message of batch.messages) {
445	      const body = message.body as Record<string, unknown>;
446	      const type = body?.type as string | undefined;
447	
448	      if (type === "plugin_job_dispatch") {
449	        const pluginJobId = body.pluginJobId as string;
450	        const pluginSlug = body.pluginSlug as string;
451	        const companyId = body.companyId as string;
452	        const executorMode = (body.executorMode as "sandbox_bridge" | "container") ?? "sandbox_bridge";
453	
454	        try {
455	          await env.PLUGIN_DISPATCH_WORKFLOW.create({
456	            id: `plugin-job-${pluginJobId}`,
457	            params: { pluginJobId, pluginSlug, companyId, executorMode },
458	          });
459	          message.ack();
460	        } catch (err) {
461	          console.error(
462	            `[Queue] Failed to start PluginDispatchWorkflow for job ${pluginJobId}: ${
463	              err instanceof Error ? err.message : String(err)
464	            }`,
465	          );
466	          message.retry();
467	        }
468	        continue;
469	      }
470	
471	      if (type === "heartbeat_dispatch") {
472	        const agentId = body.agentId as string;
473	        const companyId = body.companyId as string;
474	        const runId = body.runId as string;
475	        const taskId = body.taskId as string | undefined;
476	
477	        try {
478	          await env.HEARTBEAT_WORKFLOW.create({
479	            id: `heartbeat-${runId}`,
480	            params: { agentId, companyId, runId, taskId },
481	          });
482	          message.ack();
483	        } catch (err) {
484	          console.error(
485	            `[Queue] Failed to start HeartbeatWorkflow for run ${runId}: ${
486	              err instanceof Error ? err.message : String(err)
487	            }`,
488	          );
489	          message.retry();
490	        }
491	        continue;
492	      }
493	
494	      console.warn(`[Queue] Unknown message type: ${type}`);
495	      message.ack();
496	    }
497	  },
498	
499	  // -------------------------------------------------------------------------
500	  // Cron Triggers
501	  // -------------------------------------------------------------------------
502	  async scheduled(event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
503	    const cron = event.cron;
504	    console.log(`[Cron] Firing cron: ${cron}`);
505	
506	    if (cron === "*/5 * * * *") {
507	      const db = createHyperdriveDb(env.HYPERDRIVE);
508	      await runHeartbeatSweep(env, db);
509	    } else if (cron === "0 * * * *") {
510	      console.log("[Cron] Budget check -- not yet implemented");
511	    } else if (cron === "0 3 * * *") {
512	      console.log("[Cron] DB backup -- not yet implemented");
513	    }
514	  },
515	};
516	
517	// ---------------------------------------------------------------------------
518	// Named Durable Object + Workflow exports
519	// ---------------------------------------------------------------------------
520	
521	export { TaskDO } from "../runtime/task-do.js";
522	export { AgentRunDO } from "../runtime/agent-run-do.js";
523	export { SchedulerDO } from "../scheduler/scheduler-do.js";
524	export { HeartbeatWorkflow } from "../runtime/workflows/heartbeat.js";
525	export { PluginDispatchWorkflow } from "../runtime/workflows/plugin-dispatch.js";
